// Last completed Mon-Sun week, plus the week before it for comparison.
// Kimai reads begin/end in the user's own timezone (Europe/Lisbon).
const TZ = 'Europe/Lisbon';
const now = new Date(new Date().toLocaleString('en-US', { timeZone: TZ }));

const dayFromMonday = (now.getDay() + 6) % 7;
const mondayThisWeek = new Date(now);
mondayThisWeek.setDate(now.getDate() - dayFromMonday);

const weekStart = new Date(mondayThisWeek);
weekStart.setDate(mondayThisWeek.getDate() - 7);

const weekEnd = new Date(mondayThisWeek);
weekEnd.setDate(mondayThisWeek.getDate() - 1);

const prevStart = new Date(weekStart);
prevStart.setDate(weekStart.getDate() - 7);

const prevEnd = new Date(weekStart);
prevEnd.setDate(weekStart.getDate() - 1);

const iso = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

return [{
  json: {
    fetchBegin: `${iso(prevStart)}T00:00:00`,
    fetchEnd: `${iso(weekEnd)}T23:59:59`,
    weekStart: iso(weekStart),
    weekEnd: iso(weekEnd),
    prevStart: iso(prevStart),
    prevEnd: iso(prevEnd),
  },
}];

// Cloudflare sits in front of Kimai and rejects unfamiliar user agents, so the
// HTTP node sends an explicit User-Agent. Everything here is pure formatting.
const range = $('Week boundaries').first().json;
const entries = $input.all().map((i) => i.json).filter((e) => e && e.duration);

const inWeek = (e, from, to) => {
  const day = String(e.begin).slice(0, 10);
  return day >= from && day <= to;
};

const thisWeek = entries.filter((e) => inWeek(e, range.weekStart, range.weekEnd));
const lastWeek = entries.filter((e) => inWeek(e, range.prevStart, range.prevEnd));

const hours = (secs) => secs / 3600;
const fmtH = (h) => (h < 1 ? h.toFixed(2) : h.toFixed(1)) + ' h';
const sum = (rows) => rows.reduce((t, e) => t + e.duration, 0);

const totalThis = hours(sum(thisWeek));
const totalPrev = hours(sum(lastWeek));
const delta = totalThis - totalPrev;

// Group by customer, then project.
const byCustomer = new Map();
for (const e of thisWeek) {
  const project = e.project || (e.activity && e.activity.project) || {};
  const customer = project.customer || {};
  const cName = customer.name || 'Unassigned';
  const pName = project.name || 'Unassigned';
  if (!byCustomer.has(cName)) byCustomer.set(cName, { name: cName, secs: 0, projects: new Map() });
  const c = byCustomer.get(cName);
  c.secs += e.duration;
  c.projects.set(pName, (c.projects.get(pName) || 0) + e.duration);
}
const customers = [...byCustomer.values()].sort((a, b) => b.secs - a.secs);

// Daily totals, Monday first.
const dayNames = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const days = [];
for (let i = 0; i < 7; i++) {
  const d = new Date(`${range.weekStart}T12:00:00Z`);
  d.setUTCDate(d.getUTCDate() + i);
  const key = d.toISOString().slice(0, 10);
  const secs = sum(thisWeek.filter((e) => String(e.begin).slice(0, 10) === key));
  days.push({ label: dayNames[i], date: key, hours: hours(secs) });
}
const busiestDay = Math.max(...days.map((d) => d.hours), 0.01);

// --- formatting helpers -------------------------------------------------
const pretty = (isoDate) => {
  const d = new Date(`${isoDate}T12:00:00Z`);
  return `${d.getUTCDate()} ${['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][d.getUTCMonth()]}`;
};
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const INK = '#1b1b1a';
const MUTED = '#6f6d68';
const LINE = '#e3e0d9';
const PAPER = '#faf9f6';
const ACCENT = '#3f5f4a';

// Categorical slots, fixed order, never cycled. Validated for colour-vision
// separation against this background; slot 6 also carries the "Other" bucket.
const SERIES = ['#2a78d6', '#eb6834', '#1baf7a', '#eda100', '#e87ba4', '#4a3aa7'];
const MAX_SLICES = SERIES.length;

// Each customer keeps its own colour; past six, the tail shares the last slot.
const colourFor = (index) => SERIES[Math.min(index, MAX_SLICES - 1)];

const slices = [];
if (customers.length > MAX_SLICES) {
  customers.slice(0, MAX_SLICES - 1).forEach((c, i) => {
    slices.push({ name: c.name, secs: c.secs, colour: SERIES[i] });
  });
  const tail = customers.slice(MAX_SLICES - 1);
  slices.push({
    name: `${tail.length} others`,
    secs: tail.reduce((t, c) => t + c.secs, 0),
    colour: SERIES[MAX_SLICES - 1],
  });
} else {
  customers.forEach((c, i) => slices.push({ name: c.name, secs: c.secs, colour: SERIES[i] }));
}

// Conic gradient pie. Gmail and Apple Mail render it; Outlook desktop is served
// nothing at all rather than a misleading solid disc.
const sliceTotal = slices.reduce((t, s) => t + s.secs, 0);
let pieBlock = '';
if (sliceTotal > 0 && slices.length > 0) {
  const smallestSweep = Math.min(...slices.map((s) => (s.secs / sliceTotal) * 360));
  const gap = slices.length > 1 ? Math.min(1.5, smallestSweep / 3) : 0;
  const stops = [];
  let at = 0;
  slices.forEach((s, i) => {
    const sweep = (s.secs / sliceTotal) * 360;
    const end = i === slices.length - 1 ? 360 : at + sweep;
    const fillEnd = Math.max(at, end - gap);
    stops.push(`${s.colour} ${at.toFixed(2)}deg ${fillEnd.toFixed(2)}deg`);
    if (gap > 0) stops.push(`${PAPER} ${fillEnd.toFixed(2)}deg ${end.toFixed(2)}deg`);
    at = end;
  });
  pieBlock = `
      <!--[if !mso]><!-->
      <table role="presentation" cellpadding="0" cellspacing="0" style="width:100%;margin-top:28px;border-collapse:collapse">
        <tr><td align="center" style="padding:4px 0 2px">
          <div style="width:168px;height:168px;border-radius:50%;background-color:${PAPER};background-image:conic-gradient(${stops.join(',')})"></div>
        </td></tr>
      </table>
      <!--<![endif]-->`;
}

const deltaText = totalPrev === 0
  ? 'no entries the week before'
  : `${delta >= 0 ? '+' : '−'}${Math.abs(delta).toFixed(1)} h vs ${fmtH(totalPrev)} the week before`;

const customerRows = customers.map((c, i) => {
  const share = totalThis > 0 ? (hours(c.secs) / totalThis) * 100 : 0;
  const chip = `<span style="display:inline-block;width:10px;height:10px;border-radius:3px;background:${colourFor(i)};vertical-align:middle;margin-right:8px"></span>`;
  const projects = [...c.projects.entries()]
    .sort((a, b) => b[1] - a[1])
    .map(([name, secs]) => `<div style="color:${MUTED};font-size:13px;padding-top:3px;padding-left:18px">${esc(name)} &middot; ${fmtH(hours(secs))}</div>`)
    .join('');
  return `
    <tr>
      <td style="padding:14px 0;border-bottom:1px solid ${LINE};vertical-align:top">
        <div style="font-weight:600;font-size:15px;color:${INK}">${chip}<span style="vertical-align:middle">${esc(c.name)}</span></div>
        ${projects}
      </td>
      <td style="padding:14px 0;border-bottom:1px solid ${LINE};text-align:right;vertical-align:top;white-space:nowrap">
        <div style="font-weight:600;font-size:15px;color:${INK}">${fmtH(hours(c.secs))}</div>
        <div style="color:${MUTED};font-size:13px;padding-top:3px">${share.toFixed(0)}%</div>
      </td>
    </tr>`;
}).join('');

const dayCells = days.map((d) => {
  const height = Math.max(2, Math.round((d.hours / busiestDay) * 54));
  return `
    <td style="text-align:center;vertical-align:bottom;padding:0 4px;width:14%">
      <div style="color:${MUTED};font-size:12px;padding-bottom:4px">${d.hours > 0 ? d.hours.toFixed(1) : '–'}</div>
      <div style="background:${d.hours > 0 ? ACCENT : LINE};height:${height}px;border-radius:3px"></div>
      <div style="color:${MUTED};font-size:12px;padding-top:6px">${d.label}</div>
    </td>`;
}).join('');

const subject = `Hours ${pretty(range.weekStart)}–${pretty(range.weekEnd)}: ${fmtH(totalThis)}`;

const html = `<!-- weekly hours digest -->
<div style="margin:0;padding:24px 12px;background:${PAPER};font-family:system-ui,-apple-system,'Segoe UI',sans-serif;color:${INK}">
  <table role="presentation" cellpadding="0" cellspacing="0" style="max-width:560px;margin:0 auto;width:100%">
    <tr><td>
      <div style="color:${MUTED};font-size:13px;letter-spacing:0.04em;text-transform:uppercase">Week of ${pretty(range.weekStart)} – ${pretty(range.weekEnd)}</div>
      <div style="font-size:40px;font-weight:600;padding:6px 0 2px">${fmtH(totalThis)}</div>
      <div style="color:${MUTED};font-size:14px">${deltaText} &middot; ${thisWeek.length} entries</div>

      <table role="presentation" cellpadding="0" cellspacing="0" style="width:100%;margin-top:28px;border-top:1px solid ${LINE};border-collapse:collapse">
        <tr><td colspan="7" style="height:16px"></td></tr>
        <tr>${dayCells}</tr>
      </table>
${pieBlock}
      <table role="presentation" cellpadding="0" cellspacing="0" style="width:100%;margin-top:${pieBlock ? '12px' : '28px'};border-collapse:collapse">
        <tr>
          <td style="padding-bottom:6px;color:${MUTED};font-size:12px;letter-spacing:0.04em;text-transform:uppercase;border-bottom:1px solid ${LINE}">Client</td>
          <td style="padding-bottom:6px;color:${MUTED};font-size:12px;letter-spacing:0.04em;text-transform:uppercase;text-align:right;border-bottom:1px solid ${LINE}">Time</td>
        </tr>
        ${customerRows || `<tr><td colspan="2" style="padding:18px 0;color:${MUTED}">No time logged last week.</td></tr>`}
      </table>

      <div style="margin-top:28px;padding-top:16px;border-top:1px solid ${LINE};font-size:13px;color:${MUTED}">
        <a href="https://time.mindshine.io" style="color:${ACCENT};text-decoration:none">Open Kimai</a>
      </div>
    </td></tr>
  </table>
</div>`;

return [{ json: { subject, html, totalHours: Number(totalThis.toFixed(2)), entryCount: thisWeek.length, weekStart: range.weekStart, weekEnd: range.weekEnd } }];
